const t={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Automatizza la tua stampante con regole sicure SE-ALLORA. Disattivate per impostazione predefinita; attiva tu stesso ogni regola."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Ancora nessuna regola. Aggiungine una qui sotto, poi attivala quando sei pronto."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"Motore delle regole ATTIVO"}},off:{t:0,b:{t:2,i:[{t:3}],s:"Motore delle regole DISATTIVO"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"Attiva"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"Disattiva"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"Non viene eseguito nulla finché non sono attivi sia il motore sia la singola regola."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"Quando una stampa termina"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"Quando la stampante va in errore"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"Quando un riscaldatore sale sopra"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"Quando un riscaldatore scende sotto"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"Registra una notifica"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"Esegui un comando g-code"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"Attivata"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"Disattivata"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"Modifica"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Elimina"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"Elimina regola"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"Nome della regola"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"es. Riscaldatori spenti dopo la stampa"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"Se (trigger)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Allora (azione)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"Riscaldatore"}},value:{t:0,b:{t:2,i:[{t:3}],s:"Temperatura (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"Messaggio"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Mostrato nel registro delle regole"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"es. TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Salva regola"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annulla"}},add:{t:0,b:{t:2,i:[{t:3}],s:"Aggiungi una regola"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"Attività recente"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"notificato"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"g-code eseguito"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"saltato (stampante occupata)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"errore"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Guida"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Guida al motore delle regole"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Chiudi"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Cos'è il motore delle regole?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Osserva la stampante ed esegue un'azione quando si verifica una condizione che hai impostato - ad esempio, registra una nota quando una stampa termina o spegne i riscaldatori. Ogni regola è SE (un trigger) ALLORA (un'azione)."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Come rimane sicuro"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Il motore è disattivato per impostazione predefinita e ogni regola deve essere attivata singolarmente, così nulla viene eseguito di sorpresa. Una regola scatta una sola volta quando la sua condizione diventa vera per la prima volta. Le azioni g-code vengono eseguite solo mentre la stampante è inattiva - vengono rifiutate durante una stampa - e ogni esito viene registrato."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossario"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"Trigger"}},def:{t:0,b:{t:2,i:[{t:3}],s:"La condizione che avvia una regola, es. una stampa che termina o un riscaldatore che supera una temperatura."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"Azione"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Ciò che la regola fa quando scatta: registrare una notifica o eseguire un comando g-code (solo mentre è inattiva)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"Attivata"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Una regola che è accesa. Le regole disattivate vengono conservate ma non scattano mai."}}}}}}};export{t as default};
